### Compose-backed daemons

The default stop timeout is `5s`, but a foreground `docker compose up` needs
longer: on `SIGTERM` it stops the containers it started, and Compose gives each
one its own 10-second grace period before killing it. With the default, pitchfork
sends `SIGKILL` to the process group while Compose is still shutting containers
down, leaving them running. Raise the timeout past Compose's own grace period:

```toml
[daemons.infra]
run = "docker compose up"
stop_signal = { signal = "SIGTERM", timeout = "20s" }

[daemons.infra.hooks]
on_exit = "docker compose down --remove-orphans"
```

Increase it further if any service sets a longer `stop_grace_period` in
`docker-compose.yml`.

## Behavior

Hooks run asynchronously, so do not use `on_ready` to acquire a lock or perform
setup that must finish before the daemon can serve requests. Put required setup
in the daemon's `run` command or a dependency.


- Hooks are **fire-and-forget** — they run in the background and never block the daemon
- Hook commands run in the daemon's working directory
- Errors in hooks are logged but do not affect the daemon
- Hooks read fresh configuration from the daemon's own directory each time they
  fire, independent of the directory where the per-user supervisor started

## Examples

**Handle a failure in a script:**

```toml
[daemons.api]
run = "node server.js"
retry = 3

[daemons.api.hooks]
on_fail = "./scripts/report-failure.sh"
```

The script can read `PITCHFORK_DAEMON_ID` and `PITCHFORK_EXIT_CODE` from its
environment. Use a script for commands that need JSON encoding or complex quoting.

**Log retry attempts to a file:**

```toml
[daemons.worker]
run = "python worker.py"
retry = 5

[daemons.worker.hooks]
on_retry = "sh -c 'echo \"$(date): retry $PITCHFORK_RETRY_COUNT\" >> ./worker-retries.log'"
```

**Run cleanup on failure:**

```toml
[daemons.processor]
run = "./process-queue.sh"
retry = 2

[daemons.processor.hooks]
on_fail = "./scripts/release-locks.sh"
on_ready = "./scripts/acquire-locks.sh"
```

**Tear down infrastructure on any exit:**

```toml
[daemons.infra]
run = "docker compose up"
stop_signal = { signal = "SIGTERM", timeout = "20s" }

[daemons.infra.hooks]
on_exit = "docker compose down --remove-orphans"
```

See [compose-backed daemons](#compose-backed-daemons) for why the timeout is
raised above the default `5s`.

**Distinguish stop reason in a shared cleanup script:**

```toml
[daemons.api]
run = "npm run server"

[daemons.api.hooks]
on_exit = "sh -c 'echo \"Daemon exited: reason=$PITCHFORK_EXIT_REASON code=$PITCHFORK_EXIT_CODE\" >> ./api-exits.log'"
```

**React to a specific log message:**

```toml
[daemons.api]
run = "npm run server"
        items: [
          { text: "Quickstart", link: "/quickstart" },
          { text: "Installation", link: "/installation" },
          { text: "Your first project", link: "/first-daemon" },
          { text: "How pitchfork works", link: "/concepts/how-it-works" },
        ],
      },
      {
        text: "Run your project",
        items: [
          { text: "Guide index", link: "/guides/" },
          { text: "Shell hooks & sessions", link: "/guides/shell-hook" },
          { text: "Ready checks", link: "/guides/ready-checks" },
          { text: "File watching", link: "/guides/file-watching" },
          { text: "Automatic retries", link: "/guides/auto-restart" },
          { text: "Health checks", link: "/guides/health-checks" },
          { text: "Ports & local URLs", link: "/guides/port-management" },
          { text: "Namespaces & worktrees", link: "/concepts/namespaces" },
        ],
      },
      {
        text: "Observe & troubleshoot",
        items: [
          { text: "Logs", link: "/guides/logs" },
          { text: "Terminal dashboard", link: "/guides/tui" },
          { text: "Web dashboard", link: "/guides/web-ui" },
    /// Delay between stop and start during restart
    ///
    /// Brief pause after stopping a daemon before starting it again.
    /// Helps ensure resources (like ports) are fully released.
    #[usage(env = "PITCHFORK_RESTART_DELAY", default = "100ms", ty = "duration")]
    pub restart_delay: String,

    /// Maximum time to wait for a oneshot daemon to finish
    ///
    /// A `oneshot = true` daemon is ready when its process exits `0`, so there is no
    /// readiness check to bound the wait. `pitchfork start` gives up after this long
    /// and reports a timeout; the task itself keeps running and is still recorded as
    /// `completed` when it ends.
    ///
    /// Set to `0` for no limit. Raise it for long migrations, backfills, or seeds.
    #[usage(env = "PITCHFORK_ONESHOT_TIMEOUT", default = "1h", ty = "duration")]
    pub oneshot_timeout: String,

    /// Maximum time to wait for daemon to stop gracefully
    ///
    /// When stopping a daemon, pitchfork sends its configured signal (SIGTERM by default) and waits this long
    /// for the process to exit gracefully before sending SIGKILL.
// Check copyable examples before building and local links after rendering.
import { readFileSync, readdirSync, existsSync, statSync } from "node:fs";
import { dirname, extname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { createMarkdownRenderer } from "vitepress";
import { parse as parseToml } from "smol-toml";

const docs = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const walk = (dir) =>
  readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    if (entry.name.startsWith(".") || entry.name === "node_modules") return [];
    const path = join(dir, entry.name);
    return entry.isDirectory() ? walk(path) : [path];
  });
const errors = new Set();
const report = (file, message) =>
  errors.add(`${relative(docs, file)}: ${message}`);

if (process.argv.includes("--examples")) {
  const inputFiles = process.argv.slice(process.argv.indexOf("--examples") + 1);
  const files = inputFiles.length
    ? inputFiles.map((file) => resolve(file))
    : [
        ...walk(docs).filter((file) => file.endsWith(".md")),
        resolve(docs, "../README.md"),
      ];
  // Use the site's parser and source maps, including fences nested in lists
  // and blockquotes. Searching raw text can match a different occurrence.
  const markdown = await createMarkdownRenderer(docs, { highlight: () => "" });
  let examples = 0;
  for (const file of files) {
    const source = readFileSync(file, "utf8");
    for (const token of markdown.parse(source, {})) {
      if (token.type !== "fence") continue;
      const language = token.info.trim().split(/\s/)[0];
      if (language !== "toml" && language !== "json") continue;
      examples++;
      try {
        if (language === "toml") parseToml(token.content);
        else JSON.parse(token.content);
      } catch (error) {
        const line = token.map[0] + 1;
        report(
          file,
          `invalid ${language} example at line ${line}: ${error.message}`,
        );
      }
    }
  }
  console.log(
    `Checked ${examples} TOML/JSON examples in ${files.length} Markdown files.`,
  );
} else {
  const dist = resolve(docs, ".vitepress/dist");
  const pages = walk(dist).filter((file) => file.endsWith(".html"));
  const contents = new Map(
    pages.map((file) => [file, readFileSync(file, "utf8")]),
  );
  const ids = new Map(
    [...contents].map(([file, html]) => [
      file,
      new Set([...html.matchAll(/\bid="([^"]+)"/g)].map((match) => match[1])),
    ]),
  );
  let links = 0;
  for (const [file, html] of contents) {
    for (const match of html.matchAll(
      /<(a|img)\b[^>]*?\b(?:href|src)="([^"]+)"/g,
    )) {
      const href = match[2].replaceAll("&amp;", "&");
      if (/^(?:[a-z][a-z\d+.-]*:|\/\/)/i.test(href)) continue;
      links++;
      const currentPath = `/${relative(dist, file).replaceAll("\\", "/")}`;
      const url = new URL(href, `https://docs.example${currentPath}`);
      let target = resolve(dist, `.${decodeURIComponent(url.pathname)}`);
      if (existsSync(target) && statSync(target).isDirectory())
        target = join(target, "index.html");
      else if (!extname(target)) {
        target = existsSync(`${target}.html`)
          ? `${target}.html`
          : join(target, "index.html");
      }
      if (!existsSync(target)) {
        report(file, `missing local target ${href}`);
      } else if (url.hash && ids.has(target)) {
        const anchor = decodeURIComponent(url.hash.slice(1));
        if (anchor && !ids.get(target).has(anchor))
          report(file, `missing anchor ${href}`);
      }
    }

